          params: [['latitude', 'query', 'decimal', true, 'Широта пользователя'], ['longitude', 'query', 'decimal', true, 'Долгота пользователя'], ['radius', 'query', 'int', false, 'Метры, по умолчанию 5000'], ['page_token', 'query', 'string', false, 'Курсор следующей страницы']],
          example: 'GET /v1/search/nearby?latitude=37.776&longitude=-122.416&radius=500',
          ok: { status: '200 OK', body: { total: 37, businesses: [{ business_id: 34343, name: 'Blue Bottle', latitude: 37.7762, longitude: -122.4158, distance_m: 120 }], next_page_token: 'eyJvZmYiOjIwfQ' } },
          fields: [['total', 'Сколько мест нашлось в радиусе'], ['distance_m', 'Посчитано в LBS по точным координатам, а не по ячейке']],
          errors: [['400', 'INVALID_RADIUS', 'Радиус не из списка'], ['400', 'INVALID_COORDS', 'Широта вне −90…90 или долгота вне −180…180']],
          sql: "-- в Redis: 9 ключей параллельно\nGET geohash:6:9q8yyk   GET geohash:6:9q8yym   … (своя + 8 соседей)\n-- без кэша, в реплике индекса:\nSELECT business_id FROM geohash_index\n WHERE geohash IN ('9q8yyk', '9q8yym', '9q8yy7', …);",
