    derive: (i, deep) => {
      const p = (deep && deep.params) || {};
      const growth = p.growth || 1, peak = p.peak || 1, radius = p.radius || 1;
      const U = i.dau * 1e6 * growth, B = i.biz * 1e6 * growth;
      const search = (U * i.searches) / DAY, view = search * i.views, edits = (B * i.edits) / 100 / DAY;
      const L = LEN[radius] || 5, cell = area(L), circ = Math.PI * radius * radius;
      // quadtree из книги: лист на 100 мест (832 Б), внутренних узлов треть от листьев (64 Б).
      const leaves = B / 100;
      return {
        k: peak, peak, growth, radius, U, B, search, view, edits, L, cell, circ, density: i.density, cand: 9 * cell * i.density,
        bizGB: (B * i.bizKB) / 1e6, cacheGB: (B * 8 * 3) / 1e9, qtGB: (leaves * 832 + (leaves / 3) * 64) / 1e9,
        searchDay: U * i.searches, editDay: (B * i.edits) / 100,
      };
    },

